    for (const script of Array.from(document.scripts || [])) {
      add(script.textContent || script.innerText || '');
    }
  } catch (e) {}
  for (const source of sources) {
    const match = source.match(/EAAG[A-Za-z0-9_\\-]{20,}/);
    if (match && match[0]) return match[0];
  }
